US-004 | The `buildSetupPrompt` inventory equals the embedded key set per subtree AND follows an injected template map, which proves derivation rather than a patched hardcoded list. Species: CHANGE-DETECTION. Oracle:
bun -e '
const { buildSetupPrompt }  = await import("./src/commands/setup.ts");
const { templatesContents } = await import("./src/vendor/_generated.ts");
const basenames = (pre) => Object.keys(templatesContents).filter(x=>x.startsWith(pre)).map(x=>x.slice(pre.length)).sort();
const inv = (prompt, dest) => {
  const line = prompt.split("\n").find(l => l.trim().startsWith(dest));
  if (!line) { console.error("NO-INVENTORY-LINE " + dest); return null; }
  const m = /\(([^)]*)\)/.exec(line);
  if (!m) { console.error("NO-LIST " + dest); return null; }
  return m[1].split(",").map(s=>s.trim()).sort();
};
const CHECKS = [[".claude/commands/","commands/"],[".claude/agents/","agents/"],["scripts/cam/","scripts/cam/"]];
let rc = 0;
const real = buildSetupPrompt({ projectMode:"new", description:"x" });
for (const [dest, pre] of CHECKS) {
  const want = basenames(pre), got = inv(real, dest);
  if (JSON.stringify(want) !== JSON.stringify(got)) { console.error("MISMATCH", dest, "\n  want:", want, "\n  got: ", got); rc = 1; }
}
const probe = buildSetupPrompt({ projectMode:"new", description:"x", templates: { "commands/zzz.md":"", "agents/zzz.md":"", "scripts/cam/zzz.json":"" } });
for (const [dest] of CHECKS) {
  const g = inv(probe, dest) ?? [];
  if (!g.some(x => x.startsWith("zzz"))) { console.error("NOT-DERIVED", dest, g); rc = 1; }
}
process.exit(rc);
'
